--- sys/net/application_layer/nanocoap/nanocoap.c
+++ sys/net/application_layer/nanocoap/nanocoap.c
@@ -1294,7 +1294,70 @@

 ssize_t coap_opt_remove(coap_pkt_t *pkt, uint16_t opt_num)
 {
-    /* MASKED - implement this function */
+    /* find the option in the options array */
+    unsigned opt_idx;
+    for (opt_idx = 0; opt_idx < pkt->options_len; opt_idx++) {
+        if (pkt->options[opt_idx].opt_num == opt_num) {
+            break;
+        }
+    }
+
+    if (opt_idx >= pkt->options_len) {
+        return -ENOENT;
+    }
+
+    /* calculate byte range of the option to remove */
+    unsigned opt_start = pkt->options[opt_idx].offset;
+    unsigned opt_end;
+
+    if (opt_idx + 1 < pkt->options_len) {
+        opt_end = pkt->options[opt_idx + 1].offset;
+    }
+    else {
+        unsigned end = (uintptr_t)pkt->payload - (uintptr_t)pkt->buf;
+        if (pkt->payload_len > 0 ||
+            (end > 0 && pkt->buf[end - 1] == COAP_PAYLOAD_MARKER)) {
+            opt_end = end - 1;
+        }
+        else {
+            opt_end = end;
+        }
+    }
+
+    size_t opt_byte_len = opt_end - opt_start;
+
+    /* shift data after the removed option down */
+    size_t remaining = (pkt->payload - pkt->buf + pkt->payload_len) - opt_end;
+    memmove(pkt->buf + opt_start, pkt->buf + opt_end, remaining);
+
+    /* update offsets of options after the removed one */
+    for (unsigned i = opt_idx + 1; i < pkt->options_len; i++) {
+        pkt->options[i].offset -= opt_byte_len;
+    }
+
+    /* shift critical bits for options after the removed one */
+    for (unsigned i = opt_idx; i < pkt->options_len - 1; i++) {
+        if (bf_isset(pkt->opt_crit, i + 1)) {
+            bf_set(pkt->opt_crit, i);
+        }
+        else {
+            bf_unset(pkt->opt_crit, i);
+        }
+    }
+    bf_unset(pkt->opt_crit, pkt->options_len - 1);
+
+    /* remove the entry from the options array */
+    unsigned trailing = pkt->options_len - opt_idx - 1;
+    if (trailing) {
+        memmove(&pkt->options[opt_idx], &pkt->options[opt_idx + 1],
+                trailing * sizeof(coap_optpos_t));
+    }
+    pkt->options_len--;
+
+    /* adjust payload pointer; payload_len stays the same */
+    pkt->payload -= opt_byte_len;
+
+    return (ssize_t)opt_byte_len;
 }

