patch:
--- sys/net/credman/credman.c
+++ sys/net/credman/credman.c
@@ -272,7 +272,81 @@

 int credman_load_private_ecc_key(const void *buf, size_t buf_len, credman_credential_t *cred)
 {
-    /* MASKED - implement this function */
+    asn1_tree objects[CONFIG_CREDMAN_MAX_ASN1_OBJ];
+    asn1_tree ec_priv_key;
+
+    assert(buf);
+    assert(cred);
+
+    int obj_count = der_object_count((uint8_t *)buf, buf_len);
+    if (obj_count <= 0) {
+        DEBUG("credman: could not calculate the number of elements within the EC private key\n");
+        return CREDMAN_INVALID;
+    }
+
+    if (obj_count > CONFIG_CREDMAN_MAX_ASN1_OBJ) {
+        DEBUG("credman: not enough ASN.1 objects to decode EC private key.\n");
+        DEBUG("credman: current max is %d, and we need %d\n",
+              CONFIG_CREDMAN_MAX_ASN1_OBJ, obj_count);
+        return CREDMAN_INVALID;
+    }
+
+    if (der_decode((uint8_t *)buf, buf_len, &ec_priv_key, objects, obj_count) < 0) {
+        DEBUG("credman: could not parse the EC private key\n");
+        return CREDMAN_INVALID;
+    }
+
+    /*
+     * From https://tools.ietf.org/html/rfc5915#section-3
+     *
+     * ECPrivateKey ::= SEQUENCE {
+     *      version        INTEGER { ecPrivkeyVer1(1) } (ecPrivkeyVer1),
+     *      privateKey     OCTET STRING,
+     *      parameters [0] ECParameters {{ NamedCurve }} OPTIONAL,
+     *      publicKey  [1] BIT STRING OPTIONAL
+     * }
+     */
+
+    /* the outer container is an 'ECPrivateKey', which should be a SEQUENCE */
+    if (ec_priv_key.type != ASN1_TYPE_SEQUENCE) {
+        DEBUG("credman: the EC private key should be contained in an ASN.1 SEQUENCE\n");
+        return CREDMAN_INVALID;
+    }
+
+    /* version */
+    asn1_tree *node = ec_priv_key.child;
+    if (!node || node->type != ASN1_TYPE_INTEGER) {
+        DEBUG("credman: invalid EC private key version\n");
+        return CREDMAN_INVALID;
+    }
+
+    /* privateKey */
+    node = node->next;
+    if (!node || node->type != ASN1_TYPE_OCTET_STRING || !node->data || !node->length) {
+        DEBUG("credman: no private key found in EC private key\n");
+        return CREDMAN_INVALID;
+    }
+
+    cred->type = CREDMAN_TYPE_ECDSA;
+    cred->params.ecdsa.private_key = node->data;
+    cred->params.ecdsa.public_key.x = NULL;
+    cred->params.ecdsa.public_key.y = NULL;
+    cred->params.ecdsa.client_keys = NULL;
+    cred->params.ecdsa.client_keys_size = 0;
+
+    /* check for optional parameters [0] */
+    node = node->next;
+    if (node && (node->type == ASN1_CONTEXT_TAG(0))) {
+        node = node->next;
+    }
+
+    /* check for optional publicKey [1] */
+    if (node && (node->type == ASN1_CONTEXT_TAG(1))) {
+        return _parse_ecc_point(node->child, &cred->params.ecdsa.public_key.x,
+                                &cred->params.ecdsa.public_key.y);
+    }
+
+    return CREDMAN_OK;
 }

