--- sys/net/link_layer/ieee802154/ieee802154.c
+++ sys/net/link_layer/ieee802154/ieee802154.c
@@ -165,7 +165,62 @@

 int ieee802154_get_src(const uint8_t *mhr, uint8_t *src, le_uint16_t *src_pan)
 {
-    /* MASKED - implement this function */
+    int offset = 3; /* FCF: 0-1, Seq: 2 */
+    uint8_t tmp, type;
+
+    type = mhr[0] & IEEE802154_FCF_TYPE_MASK;
+
+    if (type == IEEE802154_FCF_TYPE_ACK) {
+        /* ACK contains no addressing fields */
+        return 0;
+    }
+
+    if (type != IEEE802154_FCF_TYPE_BEACON) {
+        /* Beacons contain no dst address */
+        tmp = mhr[1] & IEEE802154_FCF_DST_ADDR_MASK;
+        if (tmp == IEEE802154_FCF_DST_ADDR_SHORT) {
+            offset += 4;   /* 2 byte dst PAN + 2 byte dst short address */
+        }
+        else if (tmp == IEEE802154_FCF_DST_ADDR_LONG) {
+            offset += 10;  /* 2 byte dst PAN + 8 byte dst long address */
+        }
+        else if (tmp != IEEE802154_FCF_DST_ADDR_VOID) {
+            return -EINVAL;
+        }
+        else if (mhr[0] & IEEE802154_FCF_PAN_COMP) {
+            /* PAN compression, but no destination address => illegal state */
+            return -EINVAL;
+        }
+    }
+    else if (mhr[0] & IEEE802154_FCF_PAN_COMP) {
+        /* Beacon can't use PAN compression */
+        return -EINVAL;
+    }
+
+    tmp = mhr[1] & IEEE802154_FCF_SRC_ADDR_MASK;
+    if (tmp == IEEE802154_FCF_SRC_ADDR_VOID) {
+        return 0;
+    }
+
+    if (!(mhr[0] & IEEE802154_FCF_PAN_COMP)) {
+        /* read source PAN in little endian */
+        src_pan->u8[0] = mhr[offset++];
+        src_pan->u8[1] = mhr[offset++];
+    }
+
+    if (tmp == IEEE802154_FCF_SRC_ADDR_SHORT) {
+        src[1] = mhr[offset++];
+        src[0] = mhr[offset++];
+        return 2;
+    }
+    else if (tmp == IEEE802154_FCF_SRC_ADDR_LONG) {
+        for (int i = 7; i >= 0; i--) {
+            src[i] = mhr[offset++];
+        }
+        return 8;
+    }
+
+    return -EINVAL;
